CREATE TABLE sfi_result AS SELECT DISTINCT substr(-456 ISNULL, zeroblob(1000), EXISTS(SELECT DISTINCT EXISTS(SELECT DISTINCT b FROM abc ORDER BY EXISTS (SELECT DISTINCT 2147483647 UNION ALL SELECT -2147483648) ASC) FROM (SELECT c, c FROM (SELECT 456, 'injection' ORDER BY 56.1 ASC, -56.1 DESC)) GROUP BY (SELECT ALL (SELECT DISTINCT 'hardware')) HAVING (SELECT DISTINCT c FROM (SELECT ALL -2147483648, 'experiments' ORDER BY -56.1 ASC, -56.1 DESC) GROUP BY (SELECT DISTINCT 456) IN (SELECT DISTINCT 'injection') NOT IN (SELECT ALL -456) HAVING EXISTS (SELECT ALL 'injection')) UNION ALL SELECT a IN (SELECT -2147483647 UNION ALL SELECT ALL 'injection') FROM sqlite_master)) AS x, c NOTNULL ISNULL AS y FROM abc ORDER BY CAST(-56.1 AS blob) ASC;